using System;
using System.Linq;
using LastRail.Battle;
using NUnit.Framework;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
public class CombatTitleBarTests {
 static CombatSceneDriver Driver(){var p=new Ce03RailPreparation(CombatRailPreparationTests.Golden(),"a",1);var d=new CombatSceneDriver(()=>p.CreateModel(1),()=>null,(s,r)=>r+1,()=>true);d.Open();return d;}
 static GameObject View(CombatSceneDriver d){var g=new GameObject("title-test",typeof(RectTransform),typeof(Canvas));g.AddComponent<ApprovedCombatView>().Bind(d,LastRail.Resources.PreparedContent.Load<CombatPresentationAssets>("CombatPresentation/approved"));return g;}
 static Rect Bounds(RectTransform r,Transform root){var c=new Vector3[4];r.GetWorldCorners(c);var a=root.InverseTransformPoint(c[0]);var b=root.InverseTransformPoint(c[2]);float left=((RectTransform)root).rect.xMin;return Rect.MinMaxRect(a.x-left,a.y,b.x-left,b.y);}
 [Test] public void FiveFramesHaveIdenticalOuterBaselinesAndHeight(){var go=View(Driver());try{Canvas.ForceUpdateCanvases();var root=go.transform.Find("ApprovedBattle");Rect? first=null;float prior=-1;foreach(string path in new[]{"TitleHousing","WaveHousing","UltimateAuto/AutoHousing","Speed/ControlHousing","Pause/ControlHousing"}){var t=root.Find(path) as RectTransform;Assert.NotNull(t,path);var b=Bounds(t,root);Assert.That(b.height,Is.InRange(44f,56f));Assert.That(b.xMin,Is.GreaterThanOrEqualTo(prior));Assert.That(b.xMax,Is.LessThanOrEqualTo(720));if(first.HasValue){Assert.AreEqual(first.Value.yMin,b.yMin,.01);Assert.AreEqual(first.Value.yMax,b.yMax,.01);}else first=b;prior=b.xMax;}}finally{UnityEngine.Object.DestroyImmediate(go);}}
 [TestCase(1)][TestCase(10)][TestCase(15)] public void WaveTextAndProgressFitInsideOwnFrame(int wave){var go=View(Driver());try{var root=go.transform.Find("ApprovedBattle");var label=root.Find("Wave").GetComponent<TMP_Text>();label.text="웨이브 "+wave+"/15";Canvas.ForceUpdateCanvases();label.ForceMeshUpdate();var frame=root.Find("WaveHousing") as RectTransform;Assert.NotNull(frame);var outer=Bounds(frame,root);foreach(string name in new[]{"Wave","WaveProgress"}){var b=Bounds((RectTransform)root.Find(name),root);Assert.LessOrEqual(b.xMax,outer.xMax-4);Assert.GreaterOrEqual(b.xMin,outer.xMin+4);Assert.LessOrEqual(b.yMax,outer.yMax-4);Assert.GreaterOrEqual(b.yMin,outer.yMin+4);}Assert.IsFalse(label.isTextOverflowing);}finally{UnityEngine.Object.DestroyImmediate(go);}}
 [Test] public void NativeHeaderActionsKeepAutoDotFixedAndPersistPauseAndSpeeds(){var d=Driver();var go=View(d);try{var view=go.GetComponent<ApprovedCombatView>();var root=go.transform.Find("ApprovedBattle");var auto=root.Find("UltimateAuto").GetComponent<Button>();var dot=(RectTransform)auto.transform.Find("AutoThumb");var before=dot.anchoredPosition;auto.onClick.Invoke();view.Refresh();Assert.IsTrue((bool)d.HudState["ultimateAuto"]);Assert.AreEqual(before,dot.anchoredPosition);Assert.AreEqual(new Vector2(14,14),dot.sizeDelta);auto.onClick.Invoke();view.Refresh();Assert.IsFalse((bool)d.HudState["ultimateAuto"]);Assert.AreEqual(before,dot.anchoredPosition);foreach(int expected in new[]{3,4,2}){root.Find("Speed").GetComponent<Button>().onClick.Invoke();view.Refresh();Assert.AreEqual(expected,(int)d.HudState["speedHalfUnits"]);}root.Find("Pause").GetComponent<Button>().onClick.Invoke();view.Refresh();string paused=d.StateJson;d.Advance(10000000,8);Assert.AreEqual(paused,d.StateJson);root.Find("Pause").GetComponent<Button>().onClick.Invoke();view.Refresh();Assert.IsFalse((bool)d.HudState["paused"]);Assert.IsFalse(d.RecoveryRequired);}finally{UnityEngine.Object.DestroyImmediate(go);}}
 [TestCase(1280)][TestCase(1600)] public void HeaderStaysWithinActualRenderViewport(int height){var d=Driver();var go=View(d);var cameraGo=new GameObject("title-camera",typeof(Camera));var rt=new RenderTexture(720,height,24);try{var camera=cameraGo.GetComponent<Camera>();camera.targetTexture=rt;var c=go.GetComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=1;go.GetComponent<ApprovedCombatView>().Refresh();Canvas.ForceUpdateCanvases();foreach(string name in new[]{"TitleHousing","WaveHousing","UltimateAuto","Speed","Pause"}){var r=go.transform.Find("ApprovedBattle/"+name) as RectTransform;Assert.NotNull(r);var corners=new Vector3[4];r.GetWorldCorners(corners);foreach(var v in corners){var p=camera.WorldToScreenPoint(v);Assert.That(p.x,Is.InRange(0f,720f));Assert.That(p.y,Is.InRange(0f,(float)height));}}}finally{UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(cameraGo);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
}
